use crate::outcome::Outcome; #[derive(Clone,Copy,Debug,PartialEq,Eq)] pub enum FailureClass{Local,Edge,Authority,Unknown} pub fn classify<T>(o:&Outcome<T>)->Option<FailureClass>{match o{Outcome::Success(_)=>None,Outcome::Retryable(_)=>Some(FailureClass::Edge),Outcome::Permanent(_)=>Some(FailureClass::Local),Outcome::Refused(_)=>Some(FailureClass::Authority),Outcome::Unknown(_)=>Some(FailureClass::Unknown)}}
